// dice.js — Acorn d6 for Dice So Nice.
//
// A custom 3D model (dice/acorn-d6.glb, generated by tools/acorn/build_acorn.py)
// with its own physics shape: a hexagonal "long die" with pointed ends, read on
// the face that lands on top. The ends never score (face value 0), so a die
// balanced on a point still reads its nearest numbered face.
//
// Players pick it in Dice So Nice's settings ("Legend in the Mist — Acorns").
// The world setting can make it the starting look of regular dice.

import { MODULE_ID, L, modulePath } from "./constants.js";
import { ACORN_SHAPE } from "./acorn-shape.js";

export const DICE_SYSTEM_ID = "mist-hud-litm-acorn";
export const DICE_SETTINGS = { ENABLED: "acornDice", DEFAULT: "acornDiceDefault" };

export function registerDiceSettings() {
  const K = (k) => `MistHUD.settings.${k}`;
  const reg = (key, data) => { if (!game.settings.settings.has(`${MODULE_ID}.${key}`)) game.settings.register(MODULE_ID, key, data); };
  reg(DICE_SETTINGS.ENABLED, {
    name: K("acornDice.name"), hint: K("acornDice.hint"),
    scope: "world", config: true, type: Boolean, default: true, requiresReload: true,
  });
  reg(DICE_SETTINGS.DEFAULT, {
    name: K("acornDiceDefault.name"), hint: K("acornDiceDefault.hint"),
    scope: "world", config: true, type: Boolean, default: true, requiresReload: true,
  });
}

/** Load Dice So Nice's public DiceSystem class (its documented api.js). */
async function loadDiceSystemClass() {
  try {
    const url = new URL(foundry.utils.getRoute("modules/dice-so-nice/api.js"), window.location.origin).href;
    return (await import(url)).DiceSystem ?? null;
  } catch (e) {
    console.warn("Mist HUD (LitM) | Dice So Nice api.js not found, using the legacy system object", e);
    return null;
  }
}

export async function registerAcornDice(dice3d) {
  if (!dice3d || !game.settings.get(MODULE_ID, DICE_SETTINGS.ENABLED)) return;
  if (dice3d.DiceFactory?.systems?.has?.(DICE_SYSTEM_ID)) return;      // already done

  // 1. Physics shape (must exist before the preset that uses it)
  if (typeof dice3d.addDiceShape !== "function") {
    console.warn("Mist HUD (LitM) | this Dice So Nice version cannot register custom dice shapes; acorn dice disabled");
    return;
  }
  dice3d.addDiceShape(ACORN_SHAPE);   // false (and a console note) if it already exists

  // 2. Dice system, optionally the starting look of regular dice
  const name = L("dice.systemName");
  const group = "Legend in the Mist";
  const DiceSystem = await loadDiceSystemClass();
  let system;
  if (DiceSystem) {
    system = new DiceSystem(DICE_SYSTEM_ID, name, "default", group);
    if (game.settings.get(MODULE_ID, DICE_SETTINGS.DEFAULT)) system.setRoleDefaults("basic");
  } else {
    system = { id: DICE_SYSTEM_ID, name, group };
  }
  dice3d.addSystem(system);

  // 3. The d6 preset: the glTF model replaces labels/bump maps
  dice3d.addDicePreset({
    type: "d6",
    system: DICE_SYSTEM_ID,
    modelFile: modulePath("dice/acorn-d6.glb"),
  }, ACORN_SHAPE.name);
}
